#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import vm from 'node:vm';
import {selectPublishedIpa} from './published-ipa.mjs';
import {buildReleaseCatalog,selectBuildVerifiedManifest} from '../../src/gmww-release-catalog-policy.js';

const classifiedReleaseType=(process.argv[2]||process.env.GMWW_RELEASE_TYPE||'server_only').trim();
const typeRank={server_only:0,runtime:1,native:2};
let previousManifest=null;
try{previousManifest=JSON.parse(fs.readFileSync('assets/updates/latest.json','utf8'))}catch{}
let releaseType=classifiedReleaseType;
const worker='https://gmww-v2-00.williampham0702.workers.dev';
const app=fs.readFileSync('server-game/current/app.js','utf8');
const version=(app.match(/const VERSION='([^']+)'/)?.[1]||'').replace(/^V/i,'');
if(!version) throw new Error('Cannot resolve GMWW runtime version');

const outRoot=path.join('assets','updates','runtime','V'+version);
fs.rmSync(outRoot,{recursive:true,force:true});
fs.mkdirSync(outRoot,{recursive:true});

const copied=[];
function copy(src,dst){
  if(!fs.existsSync(src))return;
  const target=path.join(outRoot,dst);
  fs.mkdirSync(path.dirname(target),{recursive:true});
  fs.copyFileSync(src,target);
  copied.push(dst.replaceAll('\\','/'));
}
function copyDir(src,dst){
  if(!fs.existsSync(src))return;
  for(const name of fs.readdirSync(src)){
    const a=path.join(src,name),b=path.join(dst,name);
    const st=fs.statSync(a);
    if(st.isDirectory())copyDir(a,b); else copy(a,b);
  }
}

const leanRuntimePatch=version==='3.16';

copy('server-game/current/GMWW.html','GMWW.html');
copy('server-game/current/app.js','app.js');
copy('assets/role-card-back.webp','role-card-back.webp');
copy('server-game/current/runtime-recovery.js','runtime-recovery.js');
copy('server-game/current/gmww-local-export.js','gmww-local-export.js');
copy('server-game/current/artifact-sea-import.js','artifact-sea-import.js');
copy('server-game/current/battle-controls.js','battle-controls.js');
copy('server-game/current/action-icon-library.js','action-icon-library.js');
// Ship only the active artwork; legacy V1/V2 are preserved in the source repository.
copyDir('server-game/current/action-icons/v3','action-icons/v3');
copy('server-game/current/style.css','style.css');
copy('server-game/current/gallows-hanging.css','gallows-hanging.css');
copy('server-game/current/status-visuals.js','status-visuals.js');
copy('server-game/current/status-visuals.css','status-visuals.css');
copy('server-game/current/character-renderer.js','character-renderer.js');
copy('server-game/current/gmww-performance.js','gmww-performance.js');
copy('server-game/current/gmww-shared-motion.js','gmww-shared-motion.js');
copy('server-game/current/character-renderer.css','character-renderer.css');
copy('server-game/current/gmww-village-coast.svg','gmww-village-coast.svg');
copy('assets/village/village-layout.js','village-layout.js');
copy('assets/village/seat-leaf.webp','seat-leaf.webp');
copy('assets/village/seat-leaf.webp','village/seat-leaf.webp');
copy('assets/backgrounds/gmww-village-day-v260.webp','gmww-village-day-v260.webp');
copy('assets/backgrounds/gmww-village-night-v260.webp','gmww-village-night-v260.webp');
if(!leanRuntimePatch)copyDir('assets/characters/v253','game-characters');
copyDir('assets/characters/gmww40','characters/gmww40');
copyDir('assets/gm','gm');
copyDir('server-game/current/home-art','home-art');

// Canonical clean role artwork (63 originals, no old delivery/thumb variants).
// deploy-production.yml restores this source from the pinned V2.52 release archive
// before this script runs.
if(!leanRuntimePatch){
  const sourceRoot=path.join('server-game','legacy-assets','v252');
  const sourceManifest=path.join(sourceRoot,'role-artwork-v251.js');
  const originalRoot=path.join(sourceRoot,'assets','role-artwork-v251','original');
  if(!fs.existsSync(sourceManifest)||!fs.existsSync(originalRoot)){
    throw new Error('Canonical clean role artwork source is missing');
  }
  const ctx={window:{}};vm.createContext(ctx);
  vm.runInContext(fs.readFileSync(sourceManifest,'utf8'),ctx,{filename:'role-artwork-v251.js'});
  const source=ctx.window.GMWW_BUILTIN_ROLE_ARTWORK||{},out={};
  const entries=Object.entries(source);
  if(entries.length!==63)throw new Error('Expected 63 canonical role mappings, found '+entries.length);
  for(const [id,row] of entries){
    const sourceFile=path.join(originalRoot,id+'.webp');
    if(!fs.existsSync(sourceFile))throw new Error('Missing clean role artwork '+id);
    const rel='assets/role-artwork-v251/original/'+id+'.webp';
    copy(sourceFile,rel);
    out[id]={...row,display:rel,delivery:rel,thumb:rel,width:3072,height:2560,deliveryWidth:3072,deliveryHeight:2560};
  }
  const manifestRel='role-artwork-v251.js';
  fs.writeFileSync(path.join(outRoot,manifestRel),'window.GMWW_BUILTIN_ROLE_ARTWORK='+JSON.stringify(out)+';\n');
  copied.push(manifestRel);

  const htmlFile=path.join(outRoot,'GMWW.html');
  let html=fs.readFileSync(htmlFile,'utf8');
  if(!html.includes('role-artwork-v251.js')){
    const appScript=html.match(new RegExp('<script src="app\\.js(?:\\?v=[^"]+)?"><\\/script>'))?.[0]||'';
    if(appScript)html=html.replace(appScript,'<script src="role-artwork-v251.js"></script>\n'+appScript);
    fs.writeFileSync(htmlFile,html);
  }
  if(!html.includes('role-artwork-v251.js'))throw new Error('Runtime HTML did not load canonical role artwork manifest');
}

if(!leanRuntimePatch){
  const artwork=fs.readFileSync('server-game/shared/artwork.js','utf8');
  const m=artwork.match(/data:image\/webp;base64,([^']+)/);
  if(m){
    fs.writeFileSync(path.join(outRoot,'default-artwork.webp'),Buffer.from(m[1],'base64'));
    copied.push('default-artwork.webp');
  }
}

// Every local startup dependency referenced by the entry page must be shipped.
// A valid checksum inventory cannot rescue an HTML file pointing at absent JS.
const entryHtml=fs.readFileSync(path.join(outRoot,'GMWW.html'),'utf8');
for(const match of entryHtml.matchAll(/<script\b[^>]*\bsrc=["']([^"']+)["']/gi)){
  const source=match[1];
  if(/^(?:https?:)?\/\//i.test(source))continue;
  const local=source.split(/[?#]/)[0];
  if(local.startsWith('/')||local.split('/').some(p=>!p||p==='.'||p==='..')||!copied.includes(local))
    throw new Error('Runtime startup dependency missing or unsafe: '+local);
}
function sha(file){return crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex')}
const files=[...new Set(copied)].sort().map(rel=>({
  path:rel,
  url:`${worker}/updates/runtime/V${version}/${rel.split('/').map(encodeURIComponent).join('/')}`,
  sha256:sha(path.join(outRoot,rel))
}));

if(previousManifest?.releaseVersion===version){
  const previousType=String(previousManifest.releaseType||'server_only');
  if((typeRank[previousType]??0)>(typeRank[releaseType]??0)) releaseType=previousType;
}
const projectShell=(fs.readFileSync('server-game/GMWW-Server.xcodeproj/project.pbxproj','utf8').match(/MARKETING_VERSION = ([^;]+);/)?.[1]||'').trim();
const workerSource=fs.readFileSync('src/index.js','utf8');
const workerShell=(workerSource.match(/NATIVE_SHELL_VERSION="([^"]+)"/)?.[1]||'').trim();
if(!workerShell)throw new Error('Cannot resolve native shell version from Worker');
if(projectShell&&projectShell!==workerShell)throw new Error('Native shell version mismatch: Worker '+workerShell+' vs Xcode '+projectShell);
const shell=workerShell;
// Build-trigger/follow-up commits can be server-only even though a new native shell
// was just released. When the advertised version changed and the shell matches it,
// keep the channel native so older installs are told to download the new IPA.
const versionChanged=String(previousManifest?.releaseVersion||'')!==version;
if(releaseType==='server_only'&&versionChanged&&shell===version) releaseType='native';
// A newer runtime running on an older native shell must stay a runtime update even
// when the latest commit only touches tests/server files. Otherwise an incidental
// follow-up commit would hide the downloadable runtime package from installed apps.
// IPA packaging runs separately from the Worker/OTA pipeline. A changed Swift
// source file cannot turn the older installed shell into a native OTA release.
// Until Worker/Xcode both advertise the SAME new shell version, ship the
// independently verified Runtime package, even for mixed native+web commits.
if(version!==shell&&(releaseType==='server_only'||releaseType==='native')) releaseType='runtime';
const isNative=releaseType==='native';
let publishedIpa=null;
try{publishedIpa=JSON.parse(fs.readFileSync('update-system/published-ipa.json','utf8'))}catch{}
const manifest={
  schema:1,
  releaseVersion:version,
  releaseType,
  shellVersion:shell,
  minimumShellVersion:isNative?version:shell,
  runtimeVersion:version,
  webVersion:version,
  serverVersion:version,
  required:false,
  restartRequired:releaseType==='runtime',
  releaseNotes:["V3.283 PR654: Sửa lỗi JavaScript khiến Play Tên, Play Full, Thay thế, Xóa, Gắn Audio không nhấn được trên iPhone khi danh sách Vai Trò chưa liên kết audio xuất hiện. Bảo toàn bản V3.282; kiểm thử sự kiện nút với danh sách thiếu liên kết Full/Tên. Không thay đổi IPA, Oracle, dữ liệu Production. Rollback về Runtime trước đã được nghiệm thu.","V3.282 PR654: Thư viện Audio chỉ hiện tên Vai Trò và nút Play Tên, Play Full, Thay thế, Xóa; bỏ dòng ghi chú dưới tên. Nút Xóa hỏi xác nhận, chuyển mục vào Thùng rác có thể khôi phục mà không xóa binary file Tên/Full trong IndexedDB. Đối chiếu và sao chép danh sách Vai Trò chưa liên kết Audio Full/Tên độc lập để gắn link đúng vai, không dùng số file thiếu nguồn. Giữ nguyên IPA V3.264, Oracle và dữ liệu. Rollback về Runtime V3.281 đã nghiệm thu hoặc Production đã xác minh.","V3.281 PR654: Tách file âm thanh Tên Vai Trò khỏi audio Full; bỏ cắt đoạn tên từ lời gọi dậy. Thêm nút Play Tên, Play Full, Thay thế qua tệp hoặc URL HTTPS; Tiên Tri Hào Quang đọc lời dẫn rồi phát đúng file Tên độc lập, không cắt hoặc phát nhầm lời dậy đi. Không đổi IPA V3.264, Oracle, dữ liệu, luật chơi. Rollback về bản Runtime đã xác minh trước đó.","V3.280 PR649: Thu gọn giao diện Chia sẻ Player Web của GM trên iPhone: một URL rõ ràng, hai nút Sao chép/Gửi link cùng hàng, thông báo trạng thái ngắn. Giữ nguyên lựa chọn Cloudflare và khóa link mới cho đến khi xác thực DNS/HTTPS, giữ nguyên logic, IPA Native, Oracle, phòng và dữ liệu. Rollback Runtime V3.279.","V3.279 PR645: Khắc phục Online realtime Safari/Chrome/Edge, Chat xác thực, Đóng Băng và Lên Giàn, icon hành động neo đống lửa, double-tap Character mở tài khoản và menu GM Ngày. Nghiệm thu các trình duyệt theo lá Vai Trò/Artifact thu nhỏ, giữ IPA và dữ liệu; rollback Runtime V3.278.","V3.277 PR634: Player Web chat ngay khi vào phòng trước xếp Seat, menu trên đồng bộ Server, menu dưới đồng hồ–Chat–Khôi phục tự ẩn sau 30 giây; Chat mờ, tên và màu riêng, GM đỏ đậm, thông cáo tiêu cực có kiểm soát; lá Vai Trò/Artifact hiện khi Phát Vai, thu nhỏ thêm 50% và kéo được; icon hành động ở đống lửa, thả mục tiêu thực thi qua Server. Sửa xung đột CSS viewport iOS, giữ IPA/dữ liệu, rollback Runtime V3.276.","V3.276 PR630: Sửa giao diện Online Player Web — chỉ một cặp Vai Trò/Artifact thu nhỏ linh hoạt, menu dưới chat GM, thao tác icon trực tiếp, khóa hiệu ứng theo quyền hiển thị GM, bỏ giọng TTS tự đọc nhãn vai. Phát hành cùng Worker/Player Web sau CI, giữ nguyên IPA, dữ liệu và rollback Runtime V3.275.","V3.275 PR628: Khắc phục Artifact/Vai Trò cắt tên, lệch artwork và đóng khung GM Server khi chạm ngoài; bảo vệ chỉnh sửa, giữ IPA V3.264 và dữ liệu, rollback Runtime V3.274.","V3.274 PR613: Căn giữa artwork Artifact chỉ bằng dịch chuyển ngang, giữ nguyên tỷ lệ ảnh, không ảnh hưởng Vai Trò, bảo toàn hình gốc và dữ liệu. CI đúng phạm vi, OTA manifest SHA-256, giữ IPA V3.264. Rollback Runtime V3.273.","V3.273 PR596: Player Web Online sử dụng nền Làng; lá Vai Trò/Artifact thu nhỏ dưới Timeline; Chat 💬 đóng khi chạm ra ngoài hoặc sau 30 giây; nhãn Vai Trò riêng tư; icon V3 kéo thả dùng hành động do Server cấp theo tài khoản; đồng bộ trạng thái lượt/audio cue từ Server và kích thước icon GM. Giữ DEMO lai, GM Chat và 3 icon của GM từ V3.272, bảo toàn dữ liệu, lịch sử, IPA V3.264. Chưa đồng bộ tệp audio GM gốc; không thay đổi executor 107 lá của PR584. Rollback Runtime V3.272.","V3.272 PR595: Nút 🦩 mở Chat GM, 3 icon riêng của GM (Giết, Cứu/Hồi Sinh, Cấm/Mở chat) luôn ở bên phải timeline trong suốt ván Ngày/Đêm; kéo lên người chơi hoặc nhấn chọn, xác nhận trước khi xử lý. Không giới hạn lượt GM, dùng API phân quyền Server, cập nhật Player Web, không đổi luật Vai Trò/Artifact, giữ IPA V3.264, dữ liệu, lịch sử và rollback Runtime V3.271.","V3.271: Khắc phục Player Web DEMO đứng ở Sảnh Chờ khi GM đang chạy ván: hiển thị phòng DEMO hoạt động ngay cả khi lease danh sách cũ; tài khoản đăng nhập có thể vào ván DEMO đang chạy mà không mở khóa phòng; Player Web tự theo vào DEMO duy nhất đang chạy hoặc phòng GM đã gọi; luôn đồng bộ cảnh chơi/vòng ngày đêm/nhân vật và quyền riêng tư. Người tham gia muộn không được phát trái phép lá Vai Trò đã chốt; chỉ người được GM gán Vai Trò mới được thao tác Vai Trò, AI vẫn dự phòng chống trùng. Giữ V3.270 Audio, V3.269 DEMO lai, V3.268 Ván Mẫu, IPA V3.264 và dữ liệu, rollback V3.270.","V3.270: Sửa audio DEMO khởi động ngay trên iPhone, loại audio lượt cũ và giảm chờ khi x2/x5; Tiên Tri soi Sói Trùm bị đuổi thông báo Không phải Sói; Tiên Tri Hào Quang đọc đủ tên vai; Audio sáng và thông báo Sát Thủ, Ngày dài/đề cử/bỏ phiếu theo giai đoạn Server; đồng hồ 30 giây cuối theo tốc độ DEMO và phiếu không dồn cuối. Không đổi IPA, luật và dữ liệu; rollback V3.269.","V3.268: Bước 3 Chọn Ván Mẫu hít sát menu dưới, kéo ra tách/kéo lại hít, lưu vị trí trên iPhone, nút thu gọn/mở, không che thanh điều khiển. Kế thừa Audio sáng V3.267, Online Chat V3.266, Seat V3.265. Giữ IPA Native V3.264 và bảo toàn dữ liệu, lịch sử; Runtime OTA SHA-256, rollback V3.267.","V3.267: Sáng không ai chết, bỏ cả ba đoạn Audio: Đêm qua làng chúng ta có / số người chết / người chết, tránh đọc dở và chờ số 0; giữ Làng ơi dậy đi cùng các thông báo trạng thái. Nếu có người chết vẫn đọc đủ số lượng chính xác. Chỉ sửa Runtime OTA, giữ nguyên IPA, phòng, dữ liệu và luật; rollback V3.266.","V3.266: GMWW Online ưu tiên Chat: Ban Ngày công khai theo quyền sống/cấm, Ban Đêm kênh nhóm Vai Trò bí mật đúng lượt (màu tím), GM giám sát và cấm/mở Chat; Player Web có kênh Chat, reconnect và audio giọng đọc gọi Vai Trò, Làng ơi dậy đi (có nút tắt tiếng Player). Giữ audio hệ thống GM hiện tại, giữ chụm/banh V3.265, luật Vai Trò/Artifact, dữ liệu và lịch sử, không dùng Voice hai chiều/LiveKit, không đổi IPA V3.264. Runtime OTA SHA-256, rollback V3.265.","V3.265: Tập hợp: bỏ thanh trượt Giãn cách, thay bằng chụm/banh hai ngón iPhone, mức 50%-300% và xem trước mượt không dựng lại nhân vật; giữ nút khôi phục, kéo cả vòng, Seat/chốt vị trí. Lưu spacing/offset qua Worker và Player Web; không thay IPA Native V3.264, Vai Trò/Artifact, luật và dữ liệu. OTA SHA-256, rollback Runtime V3.264.","V3.264: Tối ưu IPA/Runtime OTA chỉ đóng gói 51 icon hành động WebP V3, loại khỏi gói 98 PNG sea-v1/v2 (giữ file gốc GitHub). Sửa 2 bộ chọn Audio $$ cho danh sách nhiều dòng. Kế thừa RULE Artifact V3.263, giữ nguyên 40 Character, lá Vai Trò/Artifact, âm thanh, phòng chơi, lịch sử, dữ liệu, rollback. Native IPA và OTA V3.264 có SHA-256; không xóa Runtime đã cài.","V3.263: Hoàn thiện ba RULE Artifact đã chốt: Bình Giấc Mơ khóa chức năng 2 chu kỳ ngày đêm và tự hết hạn; Hơi Thở Lão Già đánh dấu rồi xét chết sau đêm kế tiếp, kiểm tra miễn nhiễm; Kim Cương Phủ Nhận thu hồi Artifact dùng mãi mãi đã được sử dụng, chặn tái sử dụng và khôi phục từ bản lưu Player Web. Kế thừa trọn vẹn đống lửa V3.262, giữ Vai Trò, luật khác, phòng, lịch sử Durable Objects, dữ liệu và IPA Native V3.257; OTA SHA-256, rollback Runtime V3.262.","V3.262: Cân đều khoảng cách nhân vật đến đống lửa: tất cả từ trên, dưới, trái, phải đi đến cùng bán kính tính từ tâm lửa, thu nhỏ vòng để đứng gần lửa hơn; giữ 24 vị trí phân bố, không thay Seat, Core, Player Web, luật, dữ liệu, IPA V3.257. Đi bộ/đứng nhìn lửa/chạy về ghế tiếp tục tối ưu nhiệt, OTA SHA-256 và rollback V3.261.","V3.261: Đi bộ thật ra vị trí quanh đống lửa thay vì chỉ xoay mặt (CSS translate độc lập); đến nơi nhìn vào lửa; hết lượt hoặc đồng hồ về 0 chạy về Seat. Không tăng vòng lặp; giữ V3.260 Say Rượu, IPA 3.257, Core, dữ liệu, lịch sử. OTA SHA-256, rollback bằng Runtime mới nếu đã cập nhật.","V3.260 PR577: Say Rượu dùng mặt lưng Vai Trò gốc, lá bốc nổi đúng trong Game GM/Player; kết thúc ván dọn tạm; giữ lịch sử, luật xếp hạng số ván, IPA V3.257. OTA + thủ công SHA-256, rollback V3.259.","V3.259 PR565: Bỏ bảng nổi vết cắn Phù Thủy; giữ MỤC TIÊU, nightIntel và Cứu/Giết; phiếu đề cử số đỏ nảy nhẹ CSS trên đầu người chơi, tắt chuyển động nếu giảm hiệu ứng/tải cao; 👍👎 không khung. Kế thừa Audio V3.258; không đổi IPA V3.257, Core, Player Web, dữ liệu và DO; OTA SHA-256, rollback V3.258.","V3.258 Audio: Chuẩn hóa gọi Vai Trò, ngày mới, Làng ơi dậy đi, Ngày dài, phiếu sống/chết, số người chết, Thần Chết, 30 giây cuối, hết giờ; rollback V3.257.","V3.257: Bốn nút Tự Động, Thủ Công, Tải IPA, Đồng bộ Web trên cùng một hàng. Thủ Công chọn gói .gmwwupdate từ Tệp, kiểm tra SHA-256 trước khi cài, giữ Runtime trước để khôi phục và bảo toàn dữ liệu. Cần cài IPA hỗ trợ Thủ Công một lần. Mỗi bản phát hành kèm gói cập nhật và SHA-256.","V3.256: GM tới lượt đi bộ từ mọi góc về các vị trí trống quanh đống lửa (không bước lên tâm lửa), đứng yên hoạt động rồi chạy về đúng chỗ cũ khi hết thời gian/chuyển lượt. Bỏ hiệu ứng bay cũ, giữ mục tiêu chạy tại chỗ. Tiết kiệm năng lượng: animation GPU ngắn, idle ngủ, 15 FPS atlas; không thêm vòng lặp. Player Web, luật Core, Seat, phòng, lịch sử và IPA không thay đổi.","V3.254: Hiệu năng & Chống nóng GM mặc định Tự động; chống lịch render trùng, giảm hiệu ứng khi khung hình trễ, tạm nghỉ lúc không hoạt động. Bảo toàn V3.253 Bay/Chạy GM, 16 ô V3.252, gameplay, Player Web, dữ liệu và IPA. OTA SHA-256, rollback V3.253.","V3.253: GM Bay/Chạy — nhân vật đến lượt bay lên đúng một chiều cao; mục tiêu chạy tại chỗ. Dừng vẽ Canvas khi đứng yên, nhân vật mục tiêu giới hạn tối đa 15 FPS; nút Bay/Chạy bật/tắt để tiết kiệm pin và hạn chế nóng máy. Không hiện Player Web, không thay đổi Core, Seat, IPA, dữ liệu phòng hoặc lịch sử.","V3.251: Cân bằng chiều cao 16 ô bảo trì (82px), thu nhỏ biểu tượng mây Cloudflare (17px) và gọn nhãn; không xóa hay sửa các chức năng; bảo toàn V3.250 đã triển khai luật vào cài đặt lá bài, dữ liệu, phòng, IPA. OTA SHA-256, rollback V3.250.","V3.250: Đồng bộ luật đã chốt trực tiếp vào Cài đặt từng lá Vai Trò (Phù Thuỷ Già, Sói Tuyết, Bảo Vệ, Sói Trùm, Sói thường và Sói đặc biệt, Yêu Tinh, Phù Thuỷ, Say Rượu, Nhân Bản); thông tin, giới hạn, điều kiện và chức năng đúng Core. Sửa việc lá mặc định ghi đè luật sau cập nhật, áp dụng cả thư viện đã lưu; giữ artwork, audio, Artifact, dữ liệu và IPA V3.110. OTA SHA-256; rollback V3.249.","V3.249: Phù Thuỷ thấy vết cắn cuối sau Yêu Tinh, kể cả Bảo Vệ/Bất Tử; không thấy vết cắn khi Sói Trùm bị đóng băng hoặc đuổi. Dùng được Cứu và Giết trong một đêm. Say Rượu nhận vai người đã chết ở đêm 3; Nhân Bản kế thừa vai từ đêm sau khi mục tiêu chết. Bảo toàn dữ liệu và IPA; OTA SHA-256, rollback V3.248.","V3.248: Chỉnh 6 mức iCon thành 25/50/75/100/125/150% trên một hàng. Xóa thông báo DEMO sai vị trí khỏi Menu GM, chỉ đặt trong Hành động bên dưới khi phù hợp; Làng ơi dậy đi chỉ thuộc chuyển pha Ngày, không là ô tác vụ. Tối ưu 6 bước setup bằng bỏ POST bước trùng, giảm poll khi WebSocket mất và tránh render thừa, không đổi Core, Player Web, IPA hay dữ liệu; OTA SHA-256, rollback V3.247.","V3.247: Thêm 6 mức tăng giảm iCon hành động 75%-200% trong Cài đặt, lưu trên GM iPhone, không đổi Character. Icon Yêu Tinh 3 nhánh co theo màn hình bảo toàn ba vùng chạm. Bảo toàn Core, Player Web, IPA và dữ liệu, OTA SHA-256, rollback V3.246.","V3.246: Dùng đúng hình Yêu Tinh liền khối 3 nhánh đã duyệt, chạm trái/giữa/phải điều khiển dịch vết cắn. Icon hành động phát audio. Bảo toàn NIGHT-02 V3.245, dữ liệu/IPA, OTA SHA-256, rollback V3.245.","V3.245 NIGHT-02: Chuẩn hóa Timeline Đêm: Artifact → Bầy Sói nhận diện (nếu cần) → Phù Thuỷ Già → Sói Tuyết → Bảo Vệ → Bầy Sói Cắn chung → vai Sói có năng lực riêng theo thứ tự → Yêu Tinh → các Vai Trò còn lại. Ô Bầy Sói chỉ một Sói Cắn, gọi đủ Sói sống (Sói Tuyết chỉ được Cắn khi duy nhất sống), mỗi đêm Cắn chung tối đa một lần. Sói Trùm bị Đóng Băng: vẫn ghi nhận lựa chọn Cắn nhưng vết Cắn vô hiệu và Phù Thủy không biết nạn nhân; bị Đuổi thì khóa Cắn chung. Sói Tuyết không Đóng Băng và Bảo Vệ không bảo vệ cùng mục tiêu hai đêm liên tiếp; Bảo Vệ chỉ chặn Sói Cắn. Yêu Tinh chọn Trái/Phải hoặc Không Dịch, bỏ qua người đã chết khi dịch. Tự chuẩn hóa cài đặt lá Vai Trò đang lưu, giữ audio/artwork/cấu hình khác. Bảo toàn dữ liệu DO, phòng, lịch sử, không đổi IPA V3.110; OTA SHA-256, rollback V3.244.","V3.241: Bộ icon minh họa biển xanh–vàng kim gồm 49 ảnh riêng và 1 ảnh xoay Yêu Tinh; dùng đúng 19 ảnh đã duyệt và hoàn thiện toàn bộ danh mục. WebP 512px trong suốt, giữ kích thước 80px, kéo thả, nhiều mục tiêu và vị trí lối vào làng. Giữ cập nhật V3.240, dữ liệu tùy chỉnh, Core, Player Web, DO và IPA. OTA SHA-256, rollback V3.240.","V3.240 WITCH-01: Phù Thuỷ Già luôn thức ngay sau Bầy Sói (nếu không có Bầy Sói thì sau Artifact) dù thứ tự vai trong ván bao nhiêu. Mỗi đêm dùng tối đa một trong hai hành động Hồi Sinh hoặc Đuổi. Hồi Sinh đúng một lần trong cả ván, chỉ người chết ở ngày hoặc đêm liền trước, không tự cứu; nút Hồi Sinh tự khóa nếu không có mục tiêu hợp lệ. Không được tự Đuổi, không được Đuổi cùng một người trong hai đêm liên tiếp. Server kiểm tra hành động, người dùng, mục tiêu và lịch sử trước khi thay đổi trạng thái; GM chỉ hiển thị mục tiêu hợp lệ. Audio và Player Web tiếp tục đồng bộ như trước; bảo toàn DO/phòng/lịch sử, IPA shell V3.110. OTA SHA-256; rollback V3.239.","V3.239 WOLF-01: Bầy Sói chỉ thức dậy khi có ít nhất 2 người Sói còn sống, đếm theo người chơi kể cả trùng vai. Đêm 1 mở sau Artifact; từ đêm 2 chỉ gọi lại khi có thêm Sói mới so với đầu đêm trước. Tên Vai Trò gốc hiển thị riêng trên Character của bầy Sói, người vừa chuyển phe thêm nhãn Phe Sói; tự ẩn ngay khi kết thúc lượt/đổi pha/hết giờ. Loại bỏ toàn bộ dữ liệu Timeline có danh sách vai khỏi WebSocket công khai; API /me mới cho phép từng Sói nhìn đồng đội khi đúng lượt. Đồng bộ GMWW Runtime/Player Web 3.239, bảo toàn DO, Player/GM và IPA V3.110; CI chỉ kiểm tra luật, bảo mật, gói Web/GM, manifest SHA-256; rollback V3.238.","V3.238: toàn bộ box Menu GM dùng cùng kích thước và kiểu ON/OFF như Vai Trò: ON nền ngọc sáng viền xanh chữ trắng in đậm, OFF nền chìm chữ mờ. Đổi nhãn thành Menu, iCon, Người Chết, Đặt Menu, Đặt ⚖️, Rung; âm thanh và Auto GM giữ tên ngắn. Nhãn không đổi khi bật/tắt, trạng thái lưu và hiển thị chính xác cả Setup/Trong Trận. Các nút một lần (Đặt, Thoát, Kết thúc) có phản hồi nhấn chứ không giữ trạng thái ON giả. Không đổi luật, Player Web, IPA hoặc dữ liệu DO. OTA SHA-256, rollback V3.237.","V3.237: Menu GM dùng chung tại mọi đống lửa; nhấn lửa mở, nhấn ngoài đóng cả khi Setup và vào trận. Nút ẨN MENU dùng chữ trắng đậm và trạng thái ON/OFF giống Vai Trò/Người Chơi, giữ tuỳ chọn ẩn hai thanh trên/dưới. Thanh dưới không còn khung nền bao ngoài, các nút có icon giữ icon không chữ (Báo, Lên Giàn, Khôi phục); thời gian đồng hồ vẫn hiển thị để vận hành. Không đổi gameplay, Player Web, luật Lên Giàn, IPA hoặc DO; OTA SHA-256, rollback V3.236.","V3.236: Đống lửa mở Menu GM cả khi thiết lập và trong trận, bỏ liên kết Tạo phòng. Nút trong GM ẩn/hiện đồng thời menu trên và dưới, giữ lựa chọn trên iPhone; công cụ GM lướt ngang. Thanh dưới 62px đồng nhất mẫu Tập Hợp, các nút Báo, Lên Giàn, Khôi phục dùng icon SVG không phình ô; số đề cử trên đầu Character chỉ là số, không khung. Hòa phiếu đề cử: không ai lên giàn, không mở vote/không chết; hòa Cứu và Giết: người lên giàn sống. Đồng bộ GM/Player Web/Server. Giữ IPA, dữ liệu và Durable Objects; rollback V3.235.","V3.235: Đồng bộ menu kính mờ từ Tập Hợp đến màn Đêm/Ngày, Lên Giàn; đồng hồ cùng chiều cao nút, giữ số giây và vuốt điều chỉnh. Ngày: Đồng hồ – Báo – Hành động – Lên Giàn – Khôi phục (chữ thay icon); Đêm: Đồng hồ – Hành động – Khôi phục. 🌈 thành icon nổi kéo thả như 🐦‍🔥, nhớ vị trí GM. Rút gọn Quản Lý Cloudflare thành CLOUDFLARE. Không thay Core, Player Web, IPA, DO hoặc dữ liệu. OTA SHA-256 và rollback V3.234.","V3.234: Dock Đêm giữ Đồng hồ – Hành động – Khôi phục; sang Ngày chuyển Đồng hồ – 🏖️ – Hành động – ⛱️ – 🌈. Lên Giàn giới hạn 5 thành viên trong khung, những người còn lại cuộn dọc. Giữ đầy đủ dữ liệu và quyền chọn/vote, không thay đổi Core, Player Web, IPA hoặc DO. OTA SHA-256, rollback V3.233.","V3.233: Sửa lỗi kết nối Audio Ngày/Lên Giàn trên iPhone; VÁN GỢI Ý – AUTO VÁN – THÊM MỚI cùng hàng; QUẢN LÝ CLOUDFLARE hai dòng chuẩn kích thước; thanh dưới Đồng hồ – 🏖️ – Hành động – ⛱️ – 🌈, bỏ Khôi phục khỏi thanh dưới. Không đổi Core, Player Web, DO, IPA, dữ liệu. OTA SHA-256, rollback V3.232.","V3.232: Sửa cảnh báo lỗi ứng dụng giả trên iPhone, bỏ lỗi ảnh/CSS không có thông điệp; loại AbortError, Promise xử lý muộn, gộp trùng, hết hạn sau 15 phút. Lỗi JS thật hiển thị nội dung chẩn đoán đã che URL/token; SỬA NHANH không xóa lỗi thật. Kế thừa icon 80px V3.231, không thay đổi gameplay, Player Web, DO, IPA hoặc dữ liệu phòng. OTA SHA-256, rollback V3.231.","V3.231: Icon Vai Trò/Artifact tăng 40 lên 80px, hitbox 92px; mặc định xuất hiện tại cầu thang vào làng phía trên menu dưới, không ở đống lửa; tự xếp cách nhau, giữ kéo thả, đa mục tiêu và khôi phục. Không thay đổi Core, Player Web, dữ liệu, IPA. Rollback V3.230.","V3.230: Cài đặt → Kiểm tra & bảo trì có một box Thông báo hệ thống kính mờ đặt dưới 16 nút công cụ; gom thông báo thành công, đang xử lý, cảnh báo, lỗi; có thời gian, lịch sử tối đa 12 dòng, cuộn và Xóa. Bỏ dòng trạng thái TỐI ƯU DO chen vào lưới; Health Check, kiểm tra Server, Cache, Cloudflare, Chẩn đoán và Vận hành hiển thị kết quả tập trung. Không sửa Core, Player Web, dữ liệu phòng hoặc IPA; OTA SHA-256 và rollback V3.229.","V3.229: Trả icon hành động GM về 40px, bố trí rời nhau quanh đống lửa; khi chọn nhiều mục tiêu icon vẫn có thể tiếp tục dùng đến đủ số người. Cố định menu dưới theo Đồng hồ–🏖️/🌈–Hành động–⛱️–Khôi phục; vuốt đồng hồ Ban Ngày mỗi lần 1 phút. Kế thừa tối ưu Durable Objects V3.228, không sửa Core/Player Web/IPA/dữ liệu. OTA SHA-256 và rollback V3.228.","V3.227 GMWW Icon Action V2: icon thao tác nổi linh hoạt không khung/không nền, ảnh 49 PNG/SVG tách họa tiết khỏi huy hiệu gốc, kích thước hình bằng 1/2; xuất hiện tại đống lửa Menu GM, kéo thả khắp màn hình và giữ vị trí, hít rõ vào Character hợp lệ, chốt theo Core và khôi phục. Yêu Tinh sử dụng biểu tượng 🔄, lựa chọn hướng trái/phải giữ nguyên. Chỉ sửa giao diện icon và tài nguyên, không sửa gameplay/Player Web/IPA/dữ liệu; OTA có SHA-256 và rollback V3.226.","V3.226: Sửa icon Vai Trò/Artifact không nhìn thấy trên iPhone do lớp icon đặt sau màn hình làng toàn màn hình (z-index 125 thấp hơn 1000). Nâng lớp hiển thị icon đống lửa, giữ nguyên kéo thả/hít/chốt, BẬT/TẮT và Khôi phục theo Core. Không thay đổi gameplay, Player Web, IPA hay dữ liệu; OTA SHA-256 và rollback V3.225.","V3.225: Khắc phục ICON Vai Trò/Artifact không hiện ở đống lửa; nạp Thư viện trước app GM, dự phòng ánh xạ nếu V5 cũ thiếu, giữ icon trong lúc đồng bộ (chỉ vô hiệu thao tác), neo trong khung nhìn iPhone, kéo thả hít/chốt theo điểm thả và Core, hỗ trợ hành động không mục tiêu, khôi phục và ICON BẬT/TẮT. Không đổi gameplay/IPA/Player Web hoặc dữ liệu phòng; manifest OTA SHA-256, rollback V3.224.","V3.224: 5 icon nổi GMWW PR #501: 🚩 cờ đề cử Player Web nhỏ không khung; 🐦‍🔥 DEMO, 🌈 Thống kê phe, 🏖️ Thông cáo Làng, ⛱️ Lên Giàn nổi độc lập kéo thả và lưu vị trí. Không đổi Core, dữ liệu, IPA; OTA SHA-256 và rollback V3.223.","V3.223: Tạm thời dùng nút VÀO LÀNG từ Trang Chủ để mở Arena 3D STAGING ngay trong GMWW/iPhone bằng iframe, không chuyển ra Safari; có ‹ Trang Chủ và Chơi 2D để quay lại. Core, phòng, dữ liệu và IPA Production không thay đổi, OTA có SHA-256 và rollback V3.222.","V3.222: AUTO VÁN thông minh theo PR #504: gợi ý Ván Mẫu đúng số người lên đầu; tạo liên tiếp những đội hình khác nhau cho 3–30 người, chia Phe Dân và Sói, từ 10 người có Phe Ba từ GMWW Core; mỗi ván đủ số lá, hiển thị thống kê và xem trước rồi mới lưu khi Chọn Ván. Không thay đổi luật Vai Trò, Artifact, Player Web hoặc IPA; giữ dữ liệu phòng và có kiểm chứng OTA SHA-256, rollback phiên bản Runtime trước.","V3.219: Bỏ hoàn toàn 3 bục Top 3, hiển thị Character Idle thật theo gameCharacterId và căn giữa; hiệu ứng trôi nhẹ, giảm chuyển động khi được yêu cầu. Bảng thông tin kính mờ mạnh bán trong suốt, tất cả chữ trắng nổi bật, viền ngọc trai và ánh biển mềm mại. Không đổi tỷ lệ thắng, gameplay, Player Web, dữ liệu hoặc IPA; có OTA SHA-256 và rollback V3.218.","V3.218: Thư viện tăng lên 49 icon PNG/SVG độc lập; đối chiếu 34 actionId Vai Trò/Artifact từ kiểm kê GM và sửa ánh xạ icon riêng, giữ thiết lập người dùng V4 sang V5, không đổi gameplay, OTA có SHA-256 và rollback V3.217.","V3.217: Sửa Phù Thuỷ Già không phát ở Đêm 1 và khi là vai đầu Đêm 2 bằng cách ánh xạ riêng audio V1 source-18 với role_old_witch; không đánh dấu lượt đã đọc khi chưa phát, thử lại hữu hạn và dùng WebAudio dự phòng cho iPhone. Chuyển cue Làng ơi dậy đi sang đúng lúc Server bắt đầu Ngày, sau đó Ngày dài / Thông cáo. Đưa 5 ô gán audio Ngày, phiếu và Chốt Sống/Chết vào Thư Viện Âm Thanh Hệ Thống, sửa lưu file theo đúng category/slot và bỏ các nút audio nằm sai trang Lên Giàn. Giữ IPA, Player Web, dữ liệu, role và giao diện Top 3 V3.216; rollback Worker khi cần.","V3.216: Bục Top 3 Sea Glass và Character chiến thắng đúng vị trí, giữ nguyên nhân vật hiện có, thông tin dưới bục trong suốt và hiệu ứng nhẹ; kế thừa mọi thay đổi V3.215.","V3.215: Thư viện ICON đổi sang nhấn đúp để Sửa/Xoá; thẻ chỉ hiển thị ảnh và tên. Gán 53/54 hành động thiếu theo danh sách thực trên GM với 10 icon mới riêng biệt số 30–39, dùng chung biểu tượng tương đồng. Trong ván, icon hiện cạnh đống lửa khi đúng lượt, có Bật/Tắt tại menu GM; GM kéo tới Character sẽ chốt qua Core hiện có, hành động nhiều mục tiêu chỉ chốt khi đủ và dùng Khôi phục cũ. Hành động không có mục tiêu không bị ép kéo. Không sửa luật hoặc dữ liệu phòng; danh mục Artifact tuỳ biến vẫn yêu cầu kiểm tra riêng.","V3.213: Bổ sung 10 icon hành động số 20–29 phong cách Biển, từng PNG 1024x1024 nền trong suốt kèm SVG gốc. Thư viện ICON có 29 icon, tự gán khi và chỉ khi tên hành động trên máy GM trùng chính xác với tên biểu tượng đã định nghĩa; hỗ trợ xuất danh sách hành động chưa gán để tiếp tục triển khai. Không suy đoán mã actionId chưa kiểm kê, không đổi luật chơi, dữ liệu phòng, Player Web hoặc native IPA.","V3.212: Tinh gọn Thư viện ICON: chỉ hiện ảnh icon, tên hành động và nút Sửa/Xoá; bỏ mọi dòng mã actionId tiếng Anh và ghi chú kéo/chọn mục tiêu khỏi thẻ. Giữ tìm kiếm, chỉnh sửa, ánh xạ Vai Trò/Artifact và đủ 19 hình đã duyệt. Không đổi gameplay, Player Web, IPA hay dữ liệu phòng.","V3.210: Tích hợp bộ 19 Icon hành động GMWW chủ đề Biển được nghiệm thu: mỗi icon là PNG 1024x1024 nền trong suốt có SVG gốc, hiển thị trong Thư viện → ICON. Gán chung icon cho 26 hành động Vai Trò tương ứng, phân biệt hành động nhiều mục tiêu, chọn lá bài và 2 hướng Yêu Tinh; hỗ trợ quản lý/thêm/sửa/xoá/khôi phục và rà soát Artifact có trên máy GM. Không thay đổi hành động trong trận, luật Core, dữ liệu phòng hay Player Web; chưa kích hoạt kéo thả icon trên bản đồ và menu Bật/Tắt. Runtime cập nhật OTA trên IPA hiện có, SHA-256 toàn bộ file và rollback Runtime V3.209 khi cần.","V3.209: Sửa audio vai trò bị bỏ khi chuyển lượt đêm, Phù Thuỷ Già ở Đêm 1/2; cắt tên vai trò mặc định 5 giây và đặt được điểm cắt; khôi phục lời dẫn Ngày dài, công bố phiếu và Sống/Chết, link tải 4 cue ngay trang Lên Giàn. Tắt tiếng Xác nhận lặp trong các lượt đề cử/vote. Hiện huy hiệu ngọc biển có số đề cử trên Character đồng bộ GM và Player Web; kết luận Lên Giàn 30 giây hoặc GM xác nhận rồi sang đêm, Core ngăn nhảy pha sớm. Bảng ⚖️ riêng GM hiển thị quân số phe và dự báo có ghi rõ giả định. Hiệu ứng phán quyết và phe thắng đồng bộ Server/Player Web. Bảo toàn phòng/DO/hồ sơ, IPA shell V3.110, rollback bản trước; không chạy kiểm thử gameplay mở rộng theo yêu cầu chủ dự án. V3.208: Khôi phục audio gọi tên từng vai và xác nhận hành động; Nhà Tinh Thần Học chỉ nghe CÙNG/KHÁC PHE, không đọc vai trò; Tiên Tri trả đúng câu Người bạn soi là Sói/không phải là Sói; Tiên Tri Hào Quang nối cue Người bạn soi là với đoạn Tên cắt từ audio vai trò, chỉnh đoạn cắt bằng chạm đúp trong Thư viện Audio; rà soát vai trò thiếu nguồn audio ngay trong Thư viện. Thông cáo Làng nêu lý do Thiếu Nữ chết, Sát Thủ chọn và trả lời Chọn đúng/Chọn sai, chỉ hành động xấu có nền đỏ còn trạng thái xấu là chữ đỏ; bổ sung audio Vai Trò vào hành động ban ngày. Thông tin thay đổi của phiên bản hiện tại được giữ sau cập nhật cho đến bản mới. Không thay dữ liệu phòng/DO, không đổi IPA; có thể rollback Worker về bản Production trước khi phát hành. V3.207: Sửa luật Sói Tuyết khi là Sói duy nhất còn sống: GM xác định đúng Sói khác sống/chết theo dữ liệu Server, cho phép Cắn bên cạnh Đóng Băng theo giới hạn riêng. Không đổi IPA, dữ liệu và các luật khác. Rollback về V3.206 nếu nghiệm thu không đạt. V3.206: Cờ đề cử Player Web lớn hơn (lá cờ đỏ nổi bật). Kéo cờ gần Character đủ điều kiện có lực hút snap, viền vàng/đỏ và tên người được tô sáng rõ; thả cờ chỉ CHỌN TẠM, chưa gửi phiếu Server. Các nút OK và KHÔI PHỤC nằm ngay cạnh cờ để xác nhận hoặc trả cờ về đống lửa và chọn lại; chức năng chọn bằng danh sách vẫn giữ OK/Khôi Phục; Server kiểm tra người đủ điều kiện và giới hạn mỗi người một phiếu. Không thay đổi Seat, Card, Character, IPA hay dữ liệu trận. Rollback Runtime trước nếu nghiệm thu không đạt. V3.205: Trang Lên Giàn gọn ô TỰ ĐỘNG/THỦ CÔNG để hiển thị đủ số giây và đồng hồ; Player Web Mở Đề Cử chỉ có cờ hải tặc màu đỏ xuất hiện tại đống lửa, kéo vào Character để đề cử hoặc chạm hai lần mở lưới người đủ điều kiện theo ô Vị trí, OK và Khôi Phục trước khi xác nhận; bỏ hai box/nút Đề Cử cũ trên màn hình; Menu GM bổ sung Ẩn/Hiện Character người chết, lưu riêng trên GM không thay đổi dữ liệu hoặc Player Web. Giữ nguyên luật trò chơi, Seat, Native IPA; kiểm thử đúng phạm vi, SHA-256 và rollback Runtime trước. V3.204: Lên Giàn — Một số giây dùng chung cho Đề Cử và Vote, đồng hồ hoạt động theo từng giai đoạn; thanh Mở Đề Cử / Chốt / Mở Vote, chốt đúng giai đoạn; danh sách hiển thị đề cử realtime ngay khi Player Web gửi phiếu, khôi phục Cấm Chọn và Cấm Vote; chuyển số đã chọn/vote và chi tiết, kết luận ra box riêng; phát audio Ngày dài khi mở Lên Giàn, audio Sống/Chết khi Server chốt; không đổi luật chơi, Seat, Character, IPA hoặc dữ liệu. Khôi phục bằng rollback bản Runtime trước. Bản V3.203 và thay đổi gốc: V3.203: PR #463 — Thiết kế lại Treo Giàn: bảng thành viên còn sống tối đa 10 hàng, xếp theo đề cử; Tự động/Thủ công, chọn người rồi Chốt Sống/Chết; thời gian đề cử và bỏ phiếu riêng mặc định 60 giây ngay trong bảng, lưu sau khi rời ô, chốt sớm có xác nhận Server và đồng bộ Player Web; bỏ hai ô thời gian ở Chọn Ván, chuyển các vị trí upload audio vào Thư viện Âm thanh → Hệ thống. Bảo toàn Ván Mẫu cũ, dữ liệu phòng, DO, IPA shell V3.110; chỉ chuẩn bị ứng viên OTA, SHA-256, rollback, không triển khai Production.", "V3.202: PR #462 — Thêm ⚖ ĐẶT VỊ TRÍ TREO độc lập với tọa độ đống lửa, GM chạm vào bản đồ để lưu vị trí treo; Server lưu gallowsAnchors có kiểm tra tọa độ/revision, Player Web đồng bộ qua cấu hình Làng và cache local. Loại bỏ dây/cây/thanh trang trí phía trên Character; người bị treo dùng animation Walk có sẵn thay vì CSS rung/lắc. Giữ nguyên Seat 6–30, kết quả Lên Giàn, phòng/ván/DO và IPA V3.200; chỉ cập nhật Runtime OTA V3.202, kiểm chứng SHA-256 và rollback.", "V3.201: Treo Lên Giàn — khi xác định người lên giàn ở chế độ Tự động (bắt đầu bỏ phiếu) hoặc GM Thủ công (chọn tên), Character người đó bay lên, treo lơ lửng ngay trên 🔥 với dây treo và cử động vùng vẫy nhẹ. Đồng bộ realtime qua gallows_updated giữa GM Server/iPhone và Player Web; dựa trên candidateId và giai đoạn do Durable Object xác nhận, nhận lại trạng thái khi refresh/kết nối lại. Khi chốt Cứu/Giết, đổi chế độ, hủy hoặc Khôi phục, hiệu ứng biến mất, Character về vị trí/Seat thực; không đổi seat, người chơi, luật kết quả, role, artifact, audio hoặc dữ liệu lịch sử. CSS animation tiết kiệm pin, tôn trọng Reduce Motion; Runtime OTA V3.201, SHA-256 và rollback, IPA V3.200 giữ nguyên, không cần cài IPA mới.","V3.200: PR #457 — Thiết kế lại Lên Giàn Online/Offline/DEMO dùng chung Core Server: danh sách người còn sống theo số đề cử giảm dần, số và tỷ lệ đề cử, phiếu Cứu/Giết, Cấm đề cử/Cấm Vote và Artifact cấm Vote; GM chuyển Tự động/Thủ công bằng hộp thu gọn, kết luận theo Core Server, cập nhật Player Web bằng gallows_updated; hiển thị các mục audio để chủ dự án upload vào Thư viện. Bao gồm nền tảng từ PR #455/#456; Runtime OTA V3.200 tăng so với V3.199, SHA-256 và rollback, giữ dữ liệu/ván/phòng/Durable Objects, IPA shell OTA V3.110 tiếp tục tương thích; IPA GMWW-V3.200.ipa đã được build sạch và phát hành chính thức trên GitHub Releases, SHA-256 974cefca2dbff129d0f6c4bf50505f883814a9b9813b08199238f8bb4a2f4aa6. Mục TẢI IPA trên Server công bố V3.200, không bắt buộc cài lại IPA nếu đã dùng OTA V3.200.","V3.199: PR #453 — Sửa kéo thả nguyên đội hình Seat trên toàn bản đồ, vượt giới hạn cũ tại Y -8.4; bỏ bốn mũi tên và tọa độ X/Y, chỉ giữ thanh Giãn cách 70–135% và nút 🔄 khôi phục vị trí/giãn cách mặc định. Đồng bộ GM iPhone, Server, Player Web; không di chuyển từng Seat, không đổi người chơi hoặc số ghế. Runtime sau V3.198, bổ sung kiểm tra OTA buộc tăng phiên bản khi bytes đổi và đối chiếu SHA-256 trước phát hành; IPA shell V3.110 giữ nguyên, dữ liệu phòng/lịch sử được bảo toàn.","V3.198: Tổng hợp thay đổi Runtime đã merge sau V3.197: PR #443 sửa bảng thắng ván cũ hiện lại khi tạo/chọn ván và Phát Vai, vẫn giữ lịch sử; PR #445 neo menu GM đúng đống lửa Ngày/Đêm; PR #447 thêm DỌN RÁC SERVER có kiểm toán, không xóa tự động; PR #449 khắc phục Player Web mất roster, nhận Vai Trò/Artifact và move storm khi Phát Vai (bổ sung cho PR #439). PR #446/#448/#450 chuẩn hóa kiểm thử đúng phạm vi. Bổ sung kiểm soát SHA-256 toàn gói OTA, phát hiện các sửa đổi bị bỏ sót khi merge liên tiếp. Chỉ Runtime OTA, giữ IPA shell V3.110, dữ liệu phòng và lịch sử; không cần cài lại IPA.","V3.197: PR #439 — sửa lỗi Player Web Chrome/Edge do lời gọi handleSeatSwapRequests đã bị loại bỏ, khôi phục đầy đủ đội và realtime, nhận/mở Vai Trò cùng Artifact không cần refresh, đồng bộ đề cử và 👍/👎. IPA V3.197 đã được phát hành chính thức (SHA-256 74aa218c9081c92caf596a8adccb96d992aea3ff964598cc7add32569dc380a7); cập nhật TẢI FILE IPA trỏ đúng V3.197. Giữ shell OTA V3.110, dữ liệu, phòng chơi và Seat.","V3.196: Khắc phục kẹt triển khai Production sau PR #432: tách luồng phát hành IPA native khỏi Runtime OTA khi mã Swift và Web cùng thay đổi; Runtime V3.196 tiếp tục dùng IPA shell V3.110, kiểm tra SHA-256 và bảo vệ chống hạ phiên bản. Bổ sung cài thư viện Node trước khi chạy kiểm thử IPA, khắc phục thiếu fake-indexeddb. Gói chứa các cập nhật Server/Web đã merge và hỗ trợ DEMO giữ màn hình sáng sau khi cài IPA mới; không thay đổi dữ liệu phòng.","V3.195: Sửa Seat lệch vòng trên iPhone: dịch chuyển cả đội hình dạng khối cứng khi kéo hoặc nhấn ↑↓←→; loại bỏ ép tọa độ riêng từng Seat gần đống lửa; khi chạm mép sân cả nhóm dừng an toàn. Bỏ drag/swap từng Seat. Nút 🔄 khôi phục cùng lúc vị trí gốc X0 Y0 và giãn cách mặc định 100%, lưu Server ngay, đồng bộ Player Web/IPA Runtime qua OTA. Kiểm thử 6–30 ghế, 70–135% và hồi quy ảnh iPhone X1 Y-13.4; không chỉnh số Seat, ID, nhân vật, phòng chơi, dữ liệu.","V3.194: PR #428 — sửa lỗi Cloudflare KHÔNG KẾT NỐI khi báo cáo kiểm toán chuyển schema 1 sang schema 2; GM iPhone, trang Admin và Worker xác minh Production an toàn. Cập nhật Runtime OTA V3.194 trên IPA shell V3.110, giữ nguyên các phòng chơi, Preview và dữ liệu, không bật xóa tự động.","V3.193: Sửa nút ↑ Seat khi Y=-10 và mở rộng vùng di chuyển đội hình 6–30 Seat; kéo ngón tay trên sân để dời cả vòng Seat 4 hướng, chốt về Server khi thả tay, đồng bộ GM/Player Web. DEMO lưu và đọc lịch sử của toàn bộ ngày đêm theo ván; Thông Cáo ngày đọc nhật ký thao tác đã xác nhận, giữ đầy đủ tác động tích cực/tiêu cực và lịch sử theo từng đêm. Quy tắc Thợ Săn: mục tiêu đã săn chỉ chết khi Thợ Săn thực sự chết (ban ngày hoặc lúc rạng sáng), có log, idempotent và hỗ trợ Khôi phục lên giàn. Chỉ Runtime OTA, bảo toàn dữ liệu, không thay IPA shell V3.110.","V3.192: PR #422 — Lên Giàn: tách Tự động và GM Thủ công. Chế độ Tự động giữ đề cử/vote Player Web theo thời gian cài đặt, thêm số phiếu và tỷ lệ %, tổng cứu/giết và audio kết luận; chế độ Thủ công cho GM chọn người, chốt Sống/Chết trực tiếp không phải đợi đồng hồ. Danh sách quản lý Cấm Chọn/Cấm Vote và tác động Artifact cấm Vote trong ngày; Khôi phục áp dụng hai chế độ. Sửa kịch bản DEMO E2E theo cơ chế GM mới, nâng Runtime OTA V3.192, không nâng IPA, giữ nguyên dữ liệu và Seat. ","V3.191: Tiếp tục PR #408 — bố trí một vòng tròn 360° cho 6–30 Seat; 13 Seat Mẫu 6, 8, 10…30. Đồng bộ GM Runtime và Player Web, giữ nguyên Seat ID và kích thước Character; hỗ trợ phòng lẻ và bố cục cũ. Bảo toàn hiệu chỉnh đống lửa Ngày/Đêm, ảnh nền, dữ liệu và IPA shell V3.110.","V3.189: PR #417 — sửa menu GM bám vị trí đống lửa 🔥 theo nền Ngày/Đêm và khung nhìn; thiết kế lại Lên Giàn, đưa nút MỞ ĐỀ CỬ/BẮT ĐẦU BỎ PHIẾU lên trên phần chọn ứng viên, quản lý cấm chọn/cấm bỏ phiếu thu gọn; tự động thống kê phiếu đề cử theo từng ứng viên, tổng 👍 CỨU/👎 GIẾT và kết luận; chế độ GM THỦ CÔNG độc lập; Player Web đề cử bằng kéo cờ 🏴‍☠️ vào Character hoặc chạm đúp để mở danh sách, hiển thị 👍/👎 để bỏ phiếu; Server xác nhận mỗi phiếu, tự chốt nếu rõ người nhiều phiếu nhất và xử lý hòa đề cử bằng lựa chọn GM, hòa cứu/giết thì sống. Bổ sung hồi quy iPhone WebKit; bảo toàn dữ liệu, seat, ảnh nền và IPA V3.110.","V3.188: PR #415 — DEMO thu gọn bảng hành động thành 📗 và nhớ trạng thái; Thiếu Nữ đi thăm nhà thoát Sói cắn tại nhà mình (vẫn chết nếu thăm nhà Sói hoặc nhà có người chết); Chọn Ván Mẫu gọn hơn; lưu dock box cục bộ qua các ván; menu GM mở cạnh đống lửa 🔥. Bổ sung hồi quy WebKit iPhone và luật Thiếu Nữ; giữ nguyên dữ liệu, seat, nền, Player Web và IPA shell V3.110.","V3.187: PR #409: bảng Đang chạy hiển thị tác động mới nhất lên đầu, toàn bộ lịch sử đêm lấy từ Server trong mục thu gọn, nền kính trong hơn; Thông cáo Làng giảm độ đậm, chỉnh văn phong và thứ tự tiêu cực; giữ dữ liệu, seat và IPA. PR #411: hiệu lực chết ban đêm dời sang sáng, chỉnh luật DEMO (Phù Thủy/Bảo Vệ/Yêu Tinh), chống trùng audio, chặn Hồi sinh khi chưa có người chết và cho đặt tâm đống lửa riêng cho nền Ngày/Đêm. Triển khai Runtime OTA; không thay IPA.", "V3.186: Lưu cặp ảnh nền Ngày/Đêm trên thiết bị; mở lại dùng ảnh local, đồng bộ ngầm khi thay đổi và khôi phục mặc định bền vững. Giữ nguyên IPA, seat và dữ liệu.", "V3.185: Sửa Load failed khi Khôi phục mặc định qua đường PUT đã được hỗ trợ; GM iPhone và Player Web nạp hoàn tất nền Ngày/Đêm trước khi hiện làng, đặt ảnh tùy chỉnh trực tiếp vào lớp background thay vì đè ảnh ::after; không lóe ảnh gốc hoặc nền xanh. Giữ Seat 6–30, Character, dữ liệu và IPA không đổi.","V3.184: Phát hành PR #404: trong Cài Đặt > Chủ Đề > Bối cảnh Làng bỏ Xem trước không hỗ trợ trên iPhone IPA; đổi Xuất bản thành Áp dụng ảnh Ngày/Đêm mới và Khôi phục bản trước thành Khôi phục mặc định gốc; Server GM đồng bộ Player Web, ẩn số revision trên giao diện và tự dọn ảnh lịch sử để chỉ giữ tối đa 2 ảnh đang dùng. Bảo toàn sơ đồ Seat 6–30, Character, phòng, dữ liệu và IPA hiện có; cập nhật Runtime OTA không cần cài lại IPA.","V3.183: Khôi phục đầy đủ Seat Mẫu 6–30 người với hình tròn, hình thoi và hình chữ nhật có hai cạnh dài bên trái/phải, mỗi mẫu một vòng quanh đống lửa; loại bỏ bố trí hàng ngang theo tầng của GP2; sửa xem trước, đồng bộ GM/Player Web/Worker, giữ nguyên Seat ID, Character, ván chơi, dữ liệu và IPA V3.110.","V3.182: Khắc phục PR #400: ảnh nền Làng Ngày/Đêm chỉ hiển thị một lớp phía dưới Character/Seat, loại bỏ lớp ảnh trùng và quy tắc làm lệch tọa độ trên Player Web; bảo vệ lớp Character trên GM Server. Làm mới CSS iPhone, giữ nguyên bố trí người chơi, đống lửa, phòng, dữ liệu và IPA V3.110; có thể khôi phục ảnh nền trước.","V3.181: Sửa kết quả và audio Tiên Tri, Tiên Tri Hào Quang, Nhà Tinh Thần Học; truyền và kiểm tra Bất Tử Ban Đêm khi Sói Cắn hoặc dùng bình giết; giữ liên kết audio đã nạp, ngăn audio lượt cũ phát trễ; nối thông cáo ngày bằng câu mở đầu + số 0–30 + người chết. Áp dụng cờ bất tử đầy đủ cho ván được phân vai sau cập nhật.","V3.166: Hoàn thiện menu Ban Ngày, Thông cáo Làng và lịch sử Đêm/Ngày; quản lý Lên Giàn tự động/GM với hai quyền cấm, sửa hiển thị WebKit và phát hành OTA an toàn, giữ dữ liệu và IPA.","V3.165: Chuyển toàn bộ cài đặt Artifact sang Chọn Ván; Hành Động ban ngày mở bảng chọn bằng một chạm, hiển thị đầy đủ tên chức năng.","V3.164: Menu Ban Ngày, vuốt đồng hồ, Thông cáo Làng và hành động ngày; đồng bộ phiên bản OTA, giữ IPA và dữ liệu.","V3.163: Chọn Artifact riêng cho mỗi trận, thu gọn thiết lập thời gian, nhân vật tĩnh khi Vào Trận trên GM và Player Web, Box Hành động vuốt ngang và kéo mục tiêu không còn mũi tên; bảo toàn IPA và dữ liệu.","V3.162: Sửa Gọi Người xác nhận nhanh, âm thanh mở/đóng/tráo Artifact và tự động nhận đủ Vai Trò + Artifact trên Player Web; bảo toàn dữ liệu, IPA và rollback.","V3.161: Tổng hợp Runtime vào IPA mới, bổ sung đầy đủ Character40, hiệu ứng trạng thái, khôi phục Runtime và xuất dữ liệu; giữ dữ liệu và hỗ trợ OTA cho IPA V3.110.","V3.157: Bỏ nền xanh Character; giảm vẽ canvas dư thừa, dừng khi ẩn trang; khôi phục đi tự do và đổi đích khi đang đi. Bảo toàn dữ liệu và IPA V3.110.","V3.156: Tách nền trắng Character 11–40 trên GM Server và Player Web; giữ 4 chuyển động, bản sửa Artifact V3.155, dữ liệu và IPA V3.110.","V3.155: 5 điều chỉnh GMWW — Hủy/Xác nhận/Chọn tất cả cùng hàng, Artifact hiển thị hai từ và vuốt, điều hướng từng hành động, người bị đuổi vẫn được chọn nhưng tác động đêm vô hiệu, Artifact đầu game 30 giây.", "V3.154: Thay 40 Character mới, gồm Character 15; chỉ Idle, Walk, Run, Turn trên GM Server và Player Web; bỏ động tác ngồi, bảo toàn dữ liệu và IPA.","V3.153: Khắc phục Chọn tất cả chỉ cần một lần bấm; danh sách Sói chỉ hiện tên; Artifact hiển thị 2 ký tự có thể trượt, chức năng đúng tên; Box hành động một hàng có mũi tên và giữ kéo-thả; bảo toàn IPA V3.110 và dữ liệu.", "V3.152: Hiển thị tên Artifact dưới chân Character GM; mỗi Artifact tối đa một hành động, giữ đủ hành động Vai trò; cải thiện kéo-thả thao tác cảm ứng; duy trì dữ liệu, luật chơi, iPhone IPA V3.110 và OTA an toàn.", "V3.151: Lưu Phân Vai chuyển ngay sang Phát Vai; lá Artifact xuất hiện dưới Character GM; nhãn Đến lượt/Mục tiêu nổi bật; tên chức năng Artifact chính xác; đọc xong Xác nhận mới đổi lượt; giải thích Artifact không có hành động đêm, không thay đổi luật và IPA.", "V3.150: Ván Mẫu cấu hình riêng thời gian chọn người lên giàn và thời gian bỏ phiếu (mặc định 10 giây mỗi lượt); GM mở đề cử rồi mới bắt đầu đếm giờ, Player Web và GM cùng theo đồng hồ Server; giữ nguyên dữ liệu và IPA.", "V3.149: Kích hoạt chức năng Vai Trò và Artifact ban ngày với xác nhận Server, bảo toàn hạn mức và hậu tử; hiển thị công khai 👍/👎 trên đầu Character GM và Player Web; bổ sung chuỗi Audio/Thông Báo Làng. Giữ iOS IPA, dữ liệu và OTA an toàn.", "V3.148: Sửa tên Hành động Artifact; Thông Báo Làng và audio; hành động ban ngày theo lượt; Lên Giàn bỏ phiếu 10 giây; Sát Thủ chọn dấu bí mật và người chơi phản hồi sáng hôm sau. Giữ nguyên dữ liệu, IPA.", "V3.147: Menu đống lửa bỏ tiêu đề, vuốt tới chức năng cuối; nhãn Đến lượt/Mục tiêu luôn nằm trên trạng thái, tên và vai trò; giữ nguyên dữ liệu, luật chơi và IPA.", "V3.146: Các tab sau tác động bỏ dấu X, chạm ra ngoài để đóng, kéo thả được và dùng độ mờ kính như Timeline; giữ nguyên chức năng OK, luật chơi, dữ liệu và IPA.", "V3.145: Tích hợp bảng Cloudflare vào Cài đặt GMWW Server, xem số liệu quét trực tiếp và mở quét/dọn xác thực GitHub; giữ nguyên quyền Production, dữ liệu, OTA và IPA.", "V3.144: Sửa nút Quản lý Cloudflare mở được trên iPhone, bỏ hai đoạn chữ thừa và gỡ Công việc & Tiến độ không chính xác; bảo toàn phòng, dữ liệu và IPA.", "V3.143: Xóa Sói GM trên GM và Player Web, giữ menu đống lửa và GM online/offline; giảm polling và vòng lặp hiển thị khi nghỉ; không cần cài lại IPA, giữ dữ liệu và rollback.", "V3.140: Khắc phục OTA: bản vá SHA-256 từ inventory V3.137/V3.138, cảnh báo tải chậm, bảo toàn IPA V3.110, dữ liệu và rollback.", "V3.133: Đêm/Ngày có số thứ tự, gọi đủ Bầy Sói; sửa liên kết Audio lượt/OK/Sói Cắn/Phù Thuỷ/Sói Tuyết; hộp Yêu Tinh dịch trái-không dịch-phải và xem kết quả thật; Phù Thủy thấy vết cắn kể cả đã bảo vệ; kết quả soi nổi có thể kéo, đóng; thu gọn ONLINE/OFFLINE và ON/OFF.", "V3.132: Ghi nhận hành động ngay sau khi Server xác nhận, đồng bộ phòng ở nền; giảm xác thực lặp, ghi đo thời gian và thu hộp xác nhận chỉ còn nút OK; giữ nguyên dữ liệu, luật và Khôi phục.", "V3.131: Thu nhỏ icon Trạng Thái, xếp trạng thái - tên - vai trò trên đầu nhân vật, phục hồi màu Sói Cắn và bỏ Nhật ký dư.", "V3.130: Sửa CSS Trạng Thái ghi đè định vị Seat làm nhân vật dồn sang phải; giữ tọa độ tuyệt đối của GM và Player Web, bổ sung kiểm thử WebKit.","V3.129: Sửa triệt để Seat Mẫu không làm mới UI, ngăn chuyển động cũ đè vị trí đã gán trong các bước thiết lập; đồng bộ GM và Player Web, giữ nguyên dữ liệu và IPA.","V3.128: Viết lại vùng đi bộ trong làng và sơ đồ Seat 8–30 người lấy lửa làm tâm; chặn mái nhà, biển và sân cấm; loại bỏ vị trí ngẫu nhiên/di chuyển bù sai; giữ dữ liệu, Rule Engine và IPA.","V3.127: Khắc phục gốc lỗi Seat dồn cụm trong Vào Trận: tự hoàn tất seat chưa hợp lệ, hủy chuyển động cũ, đồng bộ vị trí GM/Player Web; bảo toàn seat, Rule Engine và dữ liệu.","V3.126: Sửa seat 12 vị trí hiển thị sai theo 24 mẫu, cho phép tick trạng thái Offline đồng bộ Online, Bảo Vệ + Săn cùng lúc, giảm tải render và lưu đầy đủ nhật ký tác động phân trang; bảo toàn dữ liệu, IPA và Rule Engine.","V3.125: Khắc phục 7 lỗi: box Tạo Phòng, Seat và căn chỉnh 4 hướng, vùng cấm, 🐺 Sói Cắn, hiệu ứng Đóng Băng trùng, giảm lag; đồng bộ GM Server/Player Web và giữ nguyên dữ liệu.","V3.124: Sửa hiển thị Bảo Vệ và Sói Cắn từ hành động xác nhận, đồng bộ hiệu ứng GM/Player Web đúng mẫu, giảm lag trên iPhone; giữ nguyên Rule, dữ liệu và IPA.","V3.123: Tích hợp 15 hiệu ứng Trạng Thái được duyệt lên nhân vật GM, Player Web và box Hành Động; bảo toàn dữ liệu và hỗ trợ Runtime OTA.","V3.122: Bổ sung phục hồi khi Runtime OTA không khởi động trên shell hiện có; giữ dữ liệu và không cần cài lại IPA. Chưa nghiệm thu trên iPhone.","V3.121: Thu gọn màn hình Tạo Phòng; bỏ lá dưới nhân vật đã vào Seat; đưa tên gần đầu; Công cụ GM một hàng vuốt ngang, giữ dữ liệu và IPA. Điều chỉnh giao diện và kiểm thử.", "V3.120: Phát hành giao diện Tạo Phòng thu gọn từ PR #264 và phục hồi luồng OTA trên iPhone bằng phiên bản Runtime mới; giữ nguyên dữ liệu và IPA đang cài.", "V3.119: Yêu Tinh: GM chọn Dịch chuyển vết cắn, chọn Trái hoặc Phải rồi OK; không chọn thì Yêu Tinh không thực hiện. Giữ nguyên dữ liệu, không cần cài lại IPA.","V3.118: Trạng thái người chơi hiện đúng trên nút hành động bị khóa (Đóng băng, Đuổi, Đã chết, Trạng thái); Tiên Tri nhận kết quả Sói / Không phải Sói riêng; giữ nguyên dữ liệu, không cần cài lại IPA.","V3.117: Xuất dữ liệu chưa đồng bộ hiển thị ngay trong app với nút Chia sẻ và Sao chép, không tải file (tránh màn hình đen trên iPhone); giữ nguyên dữ liệu, không cần cài lại IPA.","V3.116: Sửa phát hành OTA: bản Runtime 3.116 vượt phiên bản 3.115 đã quảng bá nhưng chưa tải được, để máy GM tải lại đầy đủ; giữ nguyên dữ liệu, không cần cài lại IPA.","V3.113: Thanh Đồng hồ và Hành động: người đến lượt có sao vàng lơ lửng; mục tiêu có vòng ngắm mint quay chậm và nhãn MỤC TIÊU; dấu hiệu được giữ khi realtime cập nhật; giữ nguyên dữ liệu.","V3.107: Khắc phục phát hành OTA: đồng bộ phiên bản Runtime và manifest, kiểm tra SHA-256 trước khi quảng bá bản cập nhật; bảo toàn dữ liệu và không cần cài lại IPA.","V3.106: Thêm trang Trạng Thái riêng và hiệu ứng Đóng Băng phủ nhân vật trên GM Server/Player Web; trạng thái lấy từ máy chủ, tự hết hạn, không lộ hiệu ứng riêng tư; giữ nguyên dữ liệu, không cần cài lại IPA.","V3.105: Box Hành Động bỏ tiêu đề trùng, căn giữa các nút và giữ cuộn ngang; khóa trạng thái đóng băng/đuổi hiển thị tức thời; Bầy Sói chỉ mở ở đêm đầu; sửa điều kiện đêm dùng giá trị đã chuẩn hóa; giữ dữ liệu và OTA không xóa.","V3.104: Nâng độ nhạy vuốt lượt; kéo thả mục tiêu có kiểm tra va chạm và xác nhận tên; bố cục trận giãn đều 8–30 người; thanh dưới Đồng hồ - Hành động - Khôi phục, các box Tập Hợp tự co theo chữ và Công cụ GM sắp hàng đẹp; không xóa dữ liệu.", "V3.103: Phát Audio Vai Trò/Hành Động đã nạp khi vào lượt hoặc GM chọn chức năng, có nút nghe lại cho iPhone; áp dụng giới hạn một chức năng mỗi đêm và số lượt dùng từng chức năng, cập nhật mờ nút ngay, server chặn dùng sai và khôi phục được bằng Undo; bảo toàn dữ liệu.", "V3.102: Box Hành Động dưới màn hình thu gọn theo nội dung, bỏ hướng dẫn, cuộn ngang khi nhiều chức năng; vuốt màn hình sang trái hoặc phải để chuyển lượt vai trò; giữ nguyên dữ liệu và Seat Mẫu 8–30.", "V3.101: Seat Mẫu một vòng duy nhất quanh đống lửa, tự chọn tròn / elip / chữ nhật theo số lượng 8–30; không xếp vòng trong/vòng ngoài, giữ dữ liệu GM/Player.", "V3.100: Seat Mẫu tự chọn hình 8–30 người, đống lửa làm tâm cố định, đồng bộ GM IPA và Player Web, giữ nguyên dữ liệu.", "V3.99: Vai cùng thứ tự sẽ thức dậy một lần, gom hành động trùng; box hành động cuộn ngang dưới màn hình, kéo thả hoặc nhấn đúp chọn mục tiêu, khôi phục thao tác vừa xác nhận; bảo toàn dữ liệu.", "V3.98: Đồng hồ đếm ngược dạng box nổi có thể kéo thả, bỏ thanh menu trận đấu dưới; Chọn Ván thiết lập Sói nhận diện 30 giây và Artifact đầu game 60 giây; Audio và Auto GM trong Sói GM; giữ nguyên dữ liệu.", "V3.97: Seat Mẫu 8–24 người với hình tròn, thoi, chữ nhật; vuốt ngang menu Gọi Người và chọn sơ đồ dấu chấm, đồng bộ GM và Player Web, giữ nguyên dữ liệu.", "V3.96: Khắc phục 42 chibi bị thay bằng chữ cái khi tài khoản GM offline hoặc ngồi; giữ nguyên nhân vật, phiên chơi và dữ liệu.", "V3.95: Thư Viện có Box Lab đầu tiên, mô phỏng chuỗi hiệu ứng nhiều đêm trong môi trường cách ly; không thay đổi dữ liệu trận thật.", "V3.94: Đồng hồ đếm ngược nhỏ gọn, chạy giảm thời gian ổn định; mũi tên trên chuyển về lượt trước, không thoát game; giữ nguyên dữ liệu.", "V3.93: Nhấn nhân vật sói GM đang đi trong làng để mở Hồi Sinh, Giết người, Thoát game và Kết thúc Ván. Thanh dưới là đồng hồ số, Thông Tin, icon Auto GM xoay khi bật; dữ liệu không đổi.", "V3.92: Thanh dưới chỉ icon Đồng hồ và Auto GM, chó sói GM mở Thông Tin / Thoát / Kết thúc Ván / Audio / Hồi Sinh / Giết người; bảo toàn dữ liệu.", "V3.91: Xây dựng lại menu Trận Đấu gọn trên/dưới, bỏ box che làng, thêm Hồi Sinh / Giết người thủ công; dữ liệu được giữ nguyên.", "V3.90: Cập nhật Timeline Bầy Sói / Artifact đầu ván / Vai Trò / Làng ơi dậy đi, sửa đồng bộ hành động và Auto GM, gom quản lý Artwork, giữ nguyên dữ liệu.", "V3.89: Xóa khung Khám Phá Trang Chủ, giữ ba ô hình và toàn bộ dữ liệu.", "V3.88: Một ô soạn thảo ChatGPT có prompt chuẩn, nút chẩn đoán điền báo cáo và nút Gửi riêng; không mất dữ liệu.", "V3.87: Bỏ nền hai box cuối Trang Chủ, giữ dữ liệu và thiết kế thẻ.", "V3.86: Thêm ô nhập yêu cầu bổ sung khi Báo lỗi tự động qua ChatGPT; giữ nguyên dữ liệu, Vai Trò, Artifact và cập nhật giao diện an toàn.", "V3.85: Bỏ chat AI nổi, bổ sung báo lỗi tự động ở Cài Đặt mở ChatGPT với nội dung chẩn đoán đã điền sẵn; không cần OpenAI API key.", "V3.84: Nạp 44 artwork Artifact Biển từ ZIP trong đúng phiên GM, không mất dữ liệu và đồng bộ kho server.","V3.82: Biểu tượng AI Support nổi, kéo thả; Chat hỏi đáp và Báo lỗi tự động, AI chỉ hoạt động sau khi kết nối OpenAI API.", "V3.81: Đồng bộ đèn Online/Offline trên Server cạnh tên nhân vật và GM, bỏ box trạng thái phụ.", "V3.80: Vuốt dài màn hình/chọn Timeline để điều hướng lượt, đồng hồ đếm ngược từ Ván Mẫu, Artifact theo thứ tự cấu hình và khoá Artifact đã dùng.","V3.79: Đổi chỗ menu trận: hành động ở trên, Timeline ở dưới, nút Quay về chỉ còn icon và rút gọn Bầy sói.","V3.78: Bỏ box OFFLINE · READY dưới nhân vật ở GM/Player; giữ trạng thái kết nối và game, giảm rối màn hình.","V3.77: Trang Chủ Top 3 người chơi có tỷ lệ thắng cao nhất, bục vàng bạc đồng và Nhật ký Hoạt Động Gần Đây thiết kế mới.","V3.76: Player Web tự khôi phục nhận vai sau khi GM Phát Vai, hiển thị trạng thái đang đồng bộ thay vì báo đã nhận khi chưa có dữ liệu.","V3.75: Thông báo Phát Vai và số đã xem ở box điều khiển dưới; bỏ thông báo nổi, giữ giao diện Vào Trận của V3.74.","V3.74: Giao diện Vào Trận riêng, timeline theo server, thao tác kéo thả hoặc chọn thủ công, xác nhận mục tiêu và hiệu ứng thị giác.","V3.73: Phát Vai hiển thị xác nhận Server và số Người Chơi đã xem Vai Trò; ẩn Artifact khi không sử dụng, bảo toàn dữ liệu.","V3.72: Sửa lỗi role_guard Load failed khi LƯU Ván Mẫu; đóng gói ảnh Vai Trò trên Server và giới hạn đồng bộ Artifact nền để tránh lag.","V3.71: Chọn Ván Mẫu liên kết artwork đã lưu trên Server, không truyền lại từng ảnh; Player nhận ảnh khi Phát Vai, Artifact dùng kho chung.","V3.70: Ván Mẫu chỉ đóng gói Vai Trò; Server lưu bộ Artifact dùng chung để tái sử dụng, không đóng gói lại theo từng ván.","V3.69: Khắc phục Load failed trên iPhone khi lưu Ván Mẫu; đọc Artwork chuẩn qua Server có CORS và cho phép LƯU lại không mất dữ liệu.","V3.68: Khắc phục triệt để lưu và chọn Ván Mẫu, Artwork tải theo từng lá có retry, tôn trọng Artifact đã lưu và bảo toàn dữ liệu.","V3.67: Sửa nút Chọn Ván Mẫu, Artifact không ★ vẫn được lấy theo ván, thông báo rõ lỗi và tiến độ nạp trên iPhone.","V3.65: Lá Vai Trò/Artifact Player hiển thị artwork chuẩn GM, chạm đóng và tự đóng sau 30 giây; Ván Mẫu đóng gói ảnh và nạp trước Phát Vai; đồng bộ đơn vị giây.","V3.64: Trang Phân Vai hoàn chỉnh, chia ngẫu nhiên/theo thứ tự, hoán đổi Vai Trò, điều chỉnh Artifact, chốt trước Phát Vai.","V3.63: Bổ sung lọc Tất cả / Online / Offline khi chọn Thành Viên, giữ lựa chọn khi chuyển bộ lọc và đồng bộ trạng thái","V3.62: Cho phép giữ và kéo thanh Tập hợp dân làng tới vị trí mong muốn, nhớ vị trí và tránh che timeline hoặc thanh điều khiển","V3.61: Khôi phục chỉnh thời gian sử dụng riêng từng lá Vai Trò; thời gian chung (giây) áp dụng mặc định","Chọn Ván Mẫu: hiện 3 cài đặt thời gian chung – thảo luận 300 giây, Vai Trò 30 giây, Artifact 30 giây; bỏ thời gian riêng từng lá","Chọn Ván: mặc định thảo luận 300 giây; cấu hình hạn mức Artifact theo Ngày/Đêm","Artifact ★ được chọn mặc định và vuốt ngang trên một hàng; làm gọn nhãn nhân vật trong Làng","Hiển thị đầy đủ 14 công cụ tối ưu dưới dạng lưới 3 cột và cuộn dọc; bỏ mũi tên, bộ đếm và thanh cuộn ngang","Bổ sung nút mũi tên trái/phải và thanh tiến độ để xem 14 công cụ tối ưu hệ thống theo chiều ngang; giữ nguyên chức năng và dữ liệu","Công cụ Chủ Đề: chỉ hiển thị các vị trí ảnh được kết nối với giao diện thực tế","Thay đổi hình Banner Làng Biển, Vào Làng, ba ô Khám Phá và thanh điều hướng ngay từ mục Chủ Đề","Ảnh mặc định được hiển thị trong preview; khôi phục về mặc định không làm mất dữ liệu đã lưu","Cập nhật Runtime V3.56: Player Web tự theo dõi bước chơi GM thời gian thực"],
  message:isNative?`GMWW V${version} yêu cầu cài IPA mới.`:releaseType==='runtime'?`Có GMWW V${version}. Có thể cập nhật trực tiếp.`:'Server/Player Web đã cập nhật.',
  runtime:{files:releaseType==='runtime'?files:[]},
  delete:[],
  ipa:selectPublishedIpa(publishedIpa,version,isNative?version:shell)
};
fs.mkdirSync(path.join('assets','updates'),{recursive:true});
fs.writeFileSync(path.join('assets','updates','latest.json'),JSON.stringify(manifest,null,2)+'\n');
fs.writeFileSync(path.join(outRoot,'manifest.json'),JSON.stringify(manifest,null,2)+'\n');
// Manual packages always contain the complete verified inventory, even for a native release.
fs.writeFileSync(path.join(outRoot,'manual-manifest.json'),JSON.stringify({...manifest,runtime:{files}},null,2)+'\n');
const updateChannelRev=workerSource.match(/UPDATE_CHANNEL_REV="([^"]+)"/)?.[1]||'runtime';
const revisionedManifest=path.join(outRoot,'manifest-'+updateChannelRev+'.json');
fs.writeFileSync(revisionedManifest,JSON.stringify(manifest,null,2)+'\n');
if(version!==shell){
  if(releaseType!=='runtime')throw new Error('Runtime '+version+' on shell '+shell+' must publish as runtime');
  const required=['GMWW.html','app.js','style.css','character-renderer.js','character-renderer.css','gm/gm-white-wolf.webp','home-art/home-fantasy-hero-v337.webp','home-art/home-v1-book.webp','home-art/home-v1-members.webp','home-art/home-v1-action.webp'];
  for(const p of required)if(!files.some(f=>f.path===p))throw new Error('Runtime package missing '+p);
  if(!fs.existsSync(revisionedManifest))throw new Error('Revisioned runtime manifest was not generated');
}
const catalog=releaseType==='runtime'
  ? await buildReleaseCatalog(manifest,rel=>fs.readFileSync(path.join(outRoot,rel)))
  : null;
fs.writeFileSync('src/gmww-release-catalog.js','// Generated from SHA-256 verified package bytes. Do not edit.\nexport const releaseCatalog='+JSON.stringify(catalog)+';\n');
const releaseBases=[];
// CI-audited previous inventories for V3.140. Fail closed on any missing
// evidence: all file hashes were verified by their original SUCCESS Production
// build-catalog pipeline and are pinned in version control. The IPA's native
// updater independently SHA-256 checks every downloaded changed file.
if(version==='3.140'){
  const proofFile='update-system/verified-ota-baselines-v3140.json';
  if(fs.existsSync(proofFile)){
    const pinned=JSON.parse(fs.readFileSync(proofFile,'utf8'));
    const proofs=[
      ['3.139',39109032855,'4eff650a4dc55b3b222b0ab4f661cb05707d09ff'],
      ['3.138',39104239730,'212bb552ef577cba424e8177f916ec9a38c967a0'],
      ['3.137',39096250345,'38eb1446082f105c71e84fa7dc76b286da34f6c5']
    ];
    if(pinned?.schema!==1||!Array.isArray(pinned.baselines)||pinned.baselines.length!==3)
      throw Error('Pinned OTA baseline inventory missing');
    for(const [baseVersion,workflowRun,sourceCommit] of proofs){
      const rows=pinned.baselines.filter(r=>r?.version===baseVersion);
      if(rows.length!==1)throw Error('Unverified OTA baseline '+baseVersion);
      const row=rows[0],snapshot=row.manifest;
      if(row.workflowRun!==workflowRun||row.sourceCommit!==sourceCommit||
          snapshot?.releaseVersion!==baseVersion||snapshot?.runtimeVersion!==baseVersion||
          snapshot?.shellVersion!==shell||snapshot?.releaseType!=='runtime'||
          !Array.isArray(snapshot?.runtime?.files)||snapshot.runtime.files.length!==138)
        throw Error('Pinned OTA baseline provenance mismatch '+baseVersion);
      const manifest=JSON.parse(JSON.stringify(snapshot));
      const base={schema:1,manifest,
        sha256:crypto.createHash('sha256').update(JSON.stringify(manifest)).digest('hex')};
      if(!await selectBuildVerifiedManifest(base,baseVersion,shell))
        throw Error('Pinned OTA baseline SHA-256 metadata invalid '+baseVersion);
      releaseBases.push(base);
    }
  }
}
// Only complete historical packages whose bytes are still available locally can
// become delta bases. Missing or damaged packages simply cannot enable a delta.
const packageRoot=path.dirname(outRoot);
const historical=fs.readdirSync(packageRoot).filter(name=>/^V\d+(?:\.\d+)+$/.test(name)&&name!=='V'+version)
  .sort((a,b)=>b.localeCompare(a,undefined,{numeric:true}));
for(const name of historical){
  if(releaseBases.length===3)break;
  const root=path.join(packageRoot,name);
  try{
    const base=JSON.parse(fs.readFileSync(path.join(root,'manifest.json'),'utf8'));
    if(base.shellVersion!==shell)continue;
    releaseBases.push(await buildReleaseCatalog(base,rel=>fs.readFileSync(path.join(root,rel))));
  }catch{/* Full package remains available for an unverified historical base. */}
}
fs.writeFileSync('src/gmww-release-bases.js','// Generated from verified historical package bytes. Do not edit.\nexport const releaseBases='+JSON.stringify(releaseBases)+';\n');
console.log(JSON.stringify({version,classifiedReleaseType,releaseType,files:files.length,manifest},null,2));
